from collections import deque

# BFS shortest distance on graph
def shortest_dist(graph, start, target):
    q = deque([(start, 0)])
    visited = {start}
    while q:
        node, dist = q.popleft()
        if node == target: return dist
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                q.append((neighbor, dist + 1))
    return -1

graph = {0: [1, 2], 1: [0, 3], 2: [0, 3], 3: [1, 2]}
print(f"Shortest distance 0 -> 3: {shortest_dist(graph, 0, 3)}")

def count_connected_components(n: int, edges: list[list[int]]) -> int:
    graph = {i: [] for i in range(n)}
    for u, v in edges:
        graph[u].append(v); graph[v].append(u)
    visited = set()
    components = 0
    for i in range(n):
        if i not in visited:
            components += 1
            # Launch traversal to mark entire component
            stack = [i]
            visited.add(i)
            while stack:
                curr = stack.pop()
                for neighbor in graph[curr]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        stack.append(neighbor)
    return components

print(count_connected_components(5, [[0, 1], [1, 2], [3, 4]]))

# Bipartite 2-coloring test using BFS
def is_bipartite(graph):
    color = {}
    for node in range(len(graph)):
        if node not in color:
            color[node] = 0
            q = deque([node])
            while q:
                curr = q.popleft()
                for neighbor in graph[curr]:
                    if neighbor not in color:
                        color[neighbor] = 1 - color[curr]
                        q.append(neighbor)
                    elif color[neighbor] == color[curr]:
                        return False
    return True

# Graph with odd cycle is not bipartite
print(is_bipartite([[1, 2], [0, 2], [0, 1]]))
